import React, { useContext } from 'react';

import { useConverters } from './../../pm-converters/context.js';
import { TIPTAP_FIGURE_TYPE } from './../../ricos-content/index.js';
import { RicosContext } from './../../ricos-context/index.js';
import type { GifNode } from './../../ricos-schema/next-schema/index.js';
import type { PluginProps } from './../../ricos-types/index.js';

import { getContainerClasses } from '../../_shared/figure/get-container-classes.js';
import { Giphy } from '../viewer/giphy.js';

export const Gif: React.FC<PluginProps> = ({ node, editor }) => {
  const { isMobile } = useContext(RicosContext);
  const converters = useConverters();

  const figures = editor.$nodes(TIPTAP_FIGURE_TYPE);
  const selectedFigure = figures?.find(nodePos => {
    return nodePos.node.firstChild?.attrs.id === node.attrs.id;
  })?.node;

  const ricosNode = converters.fromPmNode(selectedFigure?.toJSON()) as GifNode;

  if (!selectedFigure || !ricosNode) {
    return null;
  }

  return (
    <div
      className={getContainerClasses(editor, node.attrs.id, isMobile)}
      draggable
      data-drag-handle
    >
      <Giphy componentData={ricosNode.gifData} nodeId={node.attrs.id} />
    </div>
  );
};
