import classNames from 'classnames';

import { isNodeSelected } from './../is-node-selected.js';
import { getPluginContainerClassNames, getPluginFocusClassNames } from './../node-styles.js';
import type { Editor } from './../../tiptap/core/index.js';

export const getContainerClasses = (editor: Editor, nodeId: string, isMobile: boolean) => {
  const isFocused = isNodeSelected(editor.state, nodeId);
  return classNames(getPluginContainerClassNames(isMobile), getPluginFocusClassNames(isFocused));
};
