import { Reels, ReelsSmall } from '@wix/wix-ui-icons-common/lazy';

import { TIPTAP_GIF_TYPE } from './../ricos-content/index.js';
import type { EditorPluginCreator } from './../ricos-types/index.js';
import {
  Node_Type,
  RicosPluginToolbarNames,
  quickActionsModalSections,
} from './../ricos-types/index.js';
import { posToDOMRect } from './../tiptap/index.js';

import { pluginFigure } from '../plugin-figure/editor.js';
import { DEFAULT_CONFIGS, gifModals } from './constants.js';
import { gifConverter } from './converter/gif-converter.js';
import { getAddButtons } from './get-add-buttons.js';
import { getToolbarButtons } from './get-toolbar-buttons.js';
import { GiphyInsertModal } from './modals/insert-modal.js';
import { tiptapExtensions } from './tiptap/tiptap.js';
import type { GiphyPluginEditorConfig } from './types.js';
import { GIPHY_TYPE } from './types.js';

export const pluginGiphy: EditorPluginCreator<GiphyPluginEditorConfig> = config => {
  const pluginConfig = { type: 'giphy' as const, ...DEFAULT_CONFIGS.editor, ...config };
  return {
    config: pluginConfig,
    pmMarkConverters: [],
    pmNodeConverters: [gifConverter],
    type: GIPHY_TYPE,
    tiptapExtensions,
    getAddButtons: (config, services) => getAddButtons(config, services),
    toolbar: {
      names: [RicosPluginToolbarNames.GIF],
      getButtons: (config, services) => getToolbarButtons(config, services),
      resolveReferenceElement: tiptapEditor => {
        const startNodePos = tiptapEditor.state.selection.$from;
        if (startNodePos.nodeAfter?.type.name !== TIPTAP_GIF_TYPE) {
          return null;
        }
        return tiptapEditor.view.nodeDOM(startNodePos.pos - 1) as HTMLElement | null;
      },
    },
    getQuickActions: ({ config, pluginServices }) => {
      const isMobile = pluginServices?.context.isMobile;

      return [
        {
          id: Node_Type.GIF,
          title: 'GIF',
          icon: isMobile ? Reels : ReelsSmall,
          section: quickActionsModalSections.Media,
          tags: ['animation', 'motion', 'clip', 'short', 'funny', 'meme', 'loop'],
          command: ({ modalService, editor, referenceElement }) => {
            modalService.togglePluginPanel({
              id: gifModals.insert,
              Component: GiphyInsertModal,
              componentProps: {
                modalId: gifModals.insert,
                getGiphyUrl: config?.getGiphyUrl,
              },
              isMobile,
              positioning: {
                referenceElement: referenceElement ?? {
                  getBoundingClientRect: () =>
                    posToDOMRect(
                      editor.view,
                      editor.view.state.selection.from,
                      editor.view.state.selection.to
                    ),
                },
                placement: 'bottom-start',
              },
            });
          },
        },
      ];
    },
    dependencies: [pluginFigure],
  };
};
