import { definePmNodeConverter } from './../../pm-converters/types.js';
import { TIPTAP_FIGURE_TYPE } from './../../ricos-content/consts.js';
import { TIPTAP_GIF_TYPE, generateId } from './../../ricos-content/index.js';
import type {
  CaptionNode,
  GIFData,
  GifNode,
  Node,
  TextNode,
} from './../../ricos-schema/next-schema/index.js';
import { GIFData_GIFType, Node_Type } from './../../ricos-schema/next-schema/index.js';

export const gifConverter = definePmNodeConverter({
  toPm: {
    types: [Node_Type.GIF],
    convert: (node, visit) => {
      const fallbackCaption = {
        id: generateId(),
        type: Node_Type.CAPTION,
        nodes: [],
      } as unknown as Node;

      return {
        type: TIPTAP_FIGURE_TYPE,
        attrs: {
          id: generateId(),
        },
        content: [
          {
            type: TIPTAP_GIF_TYPE,
            attrs: {
              ...node.gifData,
              id: node.id,
            },
          },
          ...(visit?.(
            (node.nodes?.length ?? 0) > 0
              ? node
              : ({ ...node, nodes: [fallbackCaption] } as GifNode)
          ) ?? []),
        ],
      };
    },
  },
  fromPm: {
    types: [TIPTAP_FIGURE_TYPE, TIPTAP_GIF_TYPE],
    convert: (node, visit) => {
      if (node.type === TIPTAP_GIF_TYPE) {
        return undefined;
      }
      const gifNode = node.content?.find(({ type }) => type === TIPTAP_GIF_TYPE);

      if (!gifNode) {
        return undefined;
      }

      const { id, animation, ...data } = gifNode?.attrs || {};
      const gifType = data.gifType === GIFData_GIFType.STICKER ? data.gifType : undefined;

      const [captionNode] = visit?.(node) ?? [];

      return {
        type: Node_Type.GIF,
        id: id ?? generateId(),
        nodes: (captionNode?.nodes?.[0] as TextNode | undefined)?.textData?.text
          ? [captionNode as CaptionNode]
          : [],
        gifData: {
          ...data,
          gifType,
          ...(animation ? { animation } : {}),
        } as GIFData,
      };
    },
  },
});
