import type { PluginContainerData_Alignment } from './../../ricos-schema/next-schema/index.js';
import type { Resolver } from './../../ricos-types/index.js';

export const getNodeAlignment: Resolver<PluginContainerData_Alignment | undefined> = (
  _,
  __,
  editor
) => {
  const node = (editor?.state?.selection as Record<string, any> | undefined)?.node;
  if (node) {
    return node.attrs?.containerData?.alignment;
  }
  return undefined;
};
