import type { TooltipCommonProps } from '@wix/design-system';
import { Box, FieldSet, ToggleSwitch } from '@wix/design-system';
import React, { useContext } from 'react';

import { ZIndexContext } from './../../ricos-context/index.js';

type ToggleButtonProps = {
  checked: boolean;
  onChange: () => void;
  title: string;
  infoContent?: React.ReactNode;
  dataHook: string;
  size?: 'small' | 'medium' | 'large';
  toolTipSize?: 'small' | 'medium';
  tooltipAppendTo?: TooltipCommonProps['appendTo'];
  disabled?: boolean;
};

export const ToggleButton: React.FC<ToggleButtonProps> = ({
  checked,
  onChange,
  title,
  infoContent,
  dataHook,
  size,
  toolTipSize = 'medium',
  tooltipAppendTo,
  disabled,
}) => {
  const zIndexService = useContext(ZIndexContext);

  return (
    <FieldSet
      legend={title}
      legendPlacement="left"
      columns={'auto 45px'}
      alignment="center"
      infoContent={infoContent}
      infoTooltipProps={{
        appendTo:
          tooltipAppendTo ??
          (el => Boolean(el.getAttribute('data-hook')?.includes('ricos-portal'))),
        zIndex: zIndexService.getZIndex('TOOLTIP'),
        size: toolTipSize,
        enterDelay: 300,
      }}
    >
      <div />
      <Box align="right">
        <ToggleSwitch
          size={size}
          checked={checked}
          onChange={onChange}
          dataHook={dataHook}
          disabled={disabled}
        />
      </Box>
    </FieldSet>
  );
};
